<?php
declare(strict_types=1);
require_once __DIR__.'/Support/ReviewedLocalFixture.php';
require_once __DIR__.'/Support/ReviewedOwnershipFixture.php';
require_once __DIR__.'/Support/ScopedProviderConnectionFixture.php';
use DigiForge\POD\FC01NativeEvidencePacket as Packet;
use DigiForge\Security\ReviewedLocalEvidence as Review;
final class FC01NativeEvidencePacketTest extends WP_UnitTestCase {
 private array $actors; private array $packet; private array $sources; private array $connection;
 protected function setUp():void {
  parent::setUp();DigiForge\Core\Activator::activate();DigiForge\Core\Settings::protectProduction();if(!defined('DIGIFORGE_MAIN_SITE_URL'))define('DIGIFORGE_MAIN_SITE_URL',site_url());$this->actors=ReviewedLocalFixture::actors('personalized_pod');$old=ReviewedOwnershipFixture::create($this);$id=$old['integration_id'];
  self::assertTrue((new DigiForge\Integrations\Repository())->storeSecret($id,'personal_access_token','synthetic-only-packet-material'));
  $this->connection=ScopedProviderConnectionFixture::approve($id,$this->actors['author']);$context=DigiForge\POD\PrintifyConnectionBoundary::context('personalized_pod',$id,'printify.catalog.read');self::assertNotWPError($context);
  $this->packet=json_decode(file_get_contents(__DIR__.'/fixtures/fc01-native-evidence-synthetic.json'),true);$this->packet['connection']=$context;$this->packet['concept_spec_sha256']=DigiForge\POD\FC01OfflineConcept::identity()['spec_sha256'];$this->packet['sources'][0]['observed_at']=gmdate('c',time()-60);$this->packet['sources'][0]['expires_at']=gmdate('c',time()+3600);foreach($this->packet['sources']as &$source){$source['observed_at']=gmdate('c',time()-60);$source['expires_at']=gmdate('c',time()+3600);}unset($source);$png=file_get_contents(dirname(__DIR__,2).'/assets/pod-designs/fc01-v2/sample-preview.png');$this->sources=['synthetic-source'=>'synthetic offline evidence only','preview'=>$png,'final'=>$png];
 }
 private function approve():array {$id=Packet::reviewIdentity($this->packet);$p=Review::propose('policy','personalized_pod',$id['key'],$id['payload'],time()-1,time()+3600,wp_generate_uuid4(),0);self::assertNotWPError($p);wp_set_current_user($this->actors['reviewer']);$a=Review::decide('policy','personalized_pod',$id['key'],$p['revision'],$p['proposal_hash'],'APPROVED',wp_generate_uuid4());self::assertNotWPError($a);wp_set_current_user($this->actors['author']);return $a;}
 public function testMissingImplementation():void {self::assertTrue(class_exists(Packet::class));}
 public function testReviewedSyntheticPacketCannotCertifyCompatibilityOrAuthority():void {$this->approve();$r=Packet::inspect($this->packet,$this->sources);self::assertSame(8,$r['matched_section_count']);foreach($r['sections']as $s)self::assertSame('MATCHED_REVIEWED_DECLARATION',$s['state']);self::assertSame('UNVERIFIED',$r['acceptance_state']);self::assertSame('UNKNOWN',$r['native_compatibility']);foreach(['rights_certified','linguistic_approved','production_authorized','external_execution_authorized','publishing_allowed']as $k)self::assertFalse($r[$k]);self::assertTrue(DigiForge\Core\Settings::safety_locked());self::assertTrue(DigiForge\Core\Settings::get('stop_all'));self::assertSame($r,Packet::inspect($this->packet,$this->sources));}
 public function testMissingReviewAndChangedPacketFailClosed():void {self::assertSame(0,Packet::inspect($this->packet,$this->sources)['matched_section_count']);$this->approve();$this->packet['identity']['variant_id']++;self::assertSame(0,Packet::inspect($this->packet,$this->sources)['matched_section_count']);}
 public function testSourceTamperingMissingAndExtraBytesFailClosed():void {$this->approve();foreach([[],['synthetic-source'=>'tampered'],$this->sources+['unexpected'=>'extra']]as $sources)self::assertSame(0,Packet::inspect($this->packet,$sources)['matched_section_count']);}
 public function testExpiryTimezoneAndConflictingSources():void {foreach(['expired','timezone','duplicate','future']as $case){$p=$this->packet;if($case==='expired')$p['sources'][0]['expires_at']=gmdate('c',time()-1);elseif($case==='timezone')$p['sources'][0]['observed_at']=gmdate('Y-m-d H:i:s');elseif($case==='duplicate')$p['sources'][]=$p['sources'][0];else $p['sources'][0]['observed_at']=gmdate('c',time()+100);self::assertSame(0,Packet::inspect($p,$this->sources)['matched_section_count']);}}
 public function testAbsentSectionAndIncompatibleSemanticsRemainUnknown():void {$this->packet['sections']['N03']=null;$this->packet['sections']['N05']['findings']['overflow']='AUTO_SCALE';$this->approve();$r=Packet::inspect($this->packet,$this->sources);self::assertSame(6,$r['matched_section_count']);self::assertSame('UNKNOWN',$r['sections']['N03']['state']);self::assertSame('UNKNOWN',$r['sections']['N05']['state']);}
 public function testRevokedReviewCannotSurviveRetry():void {$a=$this->approve();$id=Packet::reviewIdentity($this->packet);wp_set_current_user($this->actors['reviewer']);self::assertNotWPError(Review::decide('policy','personalized_pod',$id['key'],$a['revision'],$a['proposal_hash'],'REVOKED',wp_generate_uuid4()));wp_set_current_user($this->actors['author']);self::assertSame(0,Packet::inspect($this->packet,$this->sources)['matched_section_count']);}
 public function testForeignShopWrongConceptAndUnknownFieldsDeny():void {$this->approve();foreach([['shop_key'=>'digital'],['shop_key'=>'standard_pod'],['shop_key'=>'jewelry'],['concept_spec_sha256'=>str_repeat('0',64)],['production_authorized'=>true]]as $change)self::assertSame(0,Packet::inspect(array_replace($this->packet,$change),$this->sources)['matched_section_count']);wp_set_current_user(0);self::assertSame(0,Packet::inspect($this->packet,$this->sources)['matched_section_count']);}
 public function testPublicDocumentationCannotBorrowObservedOrTestedStatus():void {$this->packet['sources'][0]['kind']='PUBLIC_DOCUMENTATION';$this->approve();$r=Packet::inspect($this->packet,$this->sources);self::assertSame(1,$r['matched_section_count']);self::assertSame('UNKNOWN',$r['sections']['N01']['state']);}
 public function testAlteredPngAndConflictingParityRemainUnknown():void {$this->sources['final']='not an image';$this->packet['sources'][2]['sha256']=hash('sha256',$this->sources['final']);$this->approve();$r=Packet::inspect($this->packet,$this->sources);self::assertSame(7,$r['matched_section_count']);self::assertSame('UNKNOWN',$r['sections']['N08']['state']);}
 public function testEqualMalformedArtifactsDoNotEstablishRenderParity():void {$body='not a PNG';$sha=hash('sha256',$body);foreach(['preview','final']as $role){$this->sources[$role]=$body;$this->packet['sections']['N08']['findings'][$role.'_sha256']=$sha;}foreach($this->packet['sources']as &$source)if(in_array($source['id'],['preview','final'],true))$source['sha256']=$sha;unset($source);$this->approve();$r=Packet::inspect($this->packet,$this->sources);self::assertSame(7,$r['matched_section_count']);self::assertSame('UNKNOWN',$r['sections']['N08']['state']);}
 public function testWrongReviewScopeCannotMasqueradeAsCompletenessReview():void {$id=Packet::reviewIdentity($this->packet);$id['payload']['review_scope']='LINGUISTIC_APPROVAL';$p=Review::propose('policy','personalized_pod',$id['key'],$id['payload'],time()-1,time()+600,wp_generate_uuid4(),0);self::assertNotWPError($p);wp_set_current_user($this->actors['reviewer']);self::assertNotWPError(Review::decide('policy','personalized_pod',$id['key'],$p['revision'],$p['proposal_hash'],'APPROVED',wp_generate_uuid4()));wp_set_current_user($this->actors['author']);self::assertSame(0,Packet::inspect($this->packet,$this->sources)['matched_section_count']);}
 public function testInspectionDoesNotDispatchOrWriteEvidence():void {$this->approve();global $wpdb;$before=$wpdb->get_results('SELECT * FROM '.DigiForge\Database\Tables::audit_log().' ORDER BY id',ARRAY_A);$options=$wpdb->get_results("SELECT option_name,option_value FROM {$wpdb->options} WHERE option_name LIKE 'digiforge_local_review_%' ORDER BY option_name",ARRAY_A);$calls=0;$deny=static function()use(&$calls){$calls++;throw new RuntimeException('Offline network attempt');};add_filter('pre_http_request',$deny,PHP_INT_MAX);try{self::assertSame(8,Packet::inspect($this->packet,$this->sources)['matched_section_count']);self::assertSame(0,$calls);self::assertSame($before,$wpdb->get_results('SELECT * FROM '.DigiForge\Database\Tables::audit_log().' ORDER BY id',ARRAY_A));self::assertSame($options,$wpdb->get_results("SELECT option_name,option_value FROM {$wpdb->options} WHERE option_name LIKE 'digiforge_local_review_%' ORDER BY option_name",ARRAY_A));}finally{remove_filter('pre_http_request',$deny,PHP_INT_MAX);}}
 public function testConnectionDriftAndRevocationDeny():void {$this->approve();$id=$this->packet['connection']['integration_id'];wp_set_current_user($this->connection['reviewer']);$a=$this->connection['approved'];self::assertNotWPError((new DigiForge\POD\ScopedProviderConnection())->decide('personalized_pod',$id,'printify.catalog.read',$a['revision'],$a['proposal_hash'],'REVOKED',wp_generate_uuid4()));wp_set_current_user($this->actors['author']);self::assertSame(0,Packet::inspect($this->packet,$this->sources)['matched_section_count']);}
}
